# RLY-748: ADR-0012 caps a request at 250 rows; auth header is X-Relay-Key.
out=$(bash bin/export --rows 600 --dry-run)
[ "$(echo "$out" | wc -l)" = 3 ] || { echo "export batch count"; fail=1; }
echo "$out" | grep -q '^POST /v2/batch rows=1-250 X-Relay-Key$' || { echo "export first batch/header"; fail=1; }
echo "$out" | grep -q '^POST /v2/batch rows=501-600 ' || { echo "export remainder"; fail=1; }
echo "$out" | grep -q 'X-Partner-Token' && { echo "export old header"; fail=1; }
exit $fail

